import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n], b = new long[n];
        long hi = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            hi = Math.max(hi, a[i]);
        }
        for (int i = 0; i < n; i++) b[i] = nextLong();
        long lo = 0;
        while (lo < hi) {
            long mid = (lo + hi) / 2, needed = 0;
            // features that cannot be developed within mid must be integrated
            for (int i = 0; i < n; i++)
                if (a[i] > mid) needed += b[i];
            if (needed <= mid) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(lo);
    }
}

