import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	b := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	for i := range b {
		b[i] = nextInt()
	}
	lo, hi := int64(0), slices.Max(a)
	for lo < hi {
		mid := (lo + hi) / 2
		var needed int64
		// features that cannot be developed within mid must be integrated
		for i := 0; i < n; i++ {
			if a[i] > mid {
				needed += b[i]
			}
		}
		if needed <= mid {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	fmt.Println(lo)
}
